SELECT t.title, n.name, cn.name, COUNT(*)
FROM title as t, movie_keyword as mk, keyword as k, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, leaf_403
WHERE ci.movie_id = t.id AND mc.movie_id = mk.movie_id AND (t.title ILIKE '%loc%') AND (kt.kind IN ('episode','movie','tv movie','video game')) AND (rt.role IN ('actor','composer','costume designer','editor','producer','production designer')) AND ci.role_id = rt.id AND mc.movie_id = t.id AND kt.id = t.kind_id AND cn.id = mc.company_id AND (cn.name ILIKE '%un%') AND ci.person_id = n.id AND k.id = mk.keyword_id AND mk.movie_id = t.id AND (n.name_pcode_nf ILIKE '%d%') AND ci.movie_id = mk.movie_id AND ct.id = mc.company_type_id AND ci.movie_id = mc.movie_id;